    history.clear();
    forward = history.end();
    backward = history.begin();
}

void RBX::ChangeHistoryService::setEnabled(bool value)
{
    Security::Context::current().requirePermission(Security::Administrator, "ChangeHistoryService.enabled");
    if (value != enabled) {
