{
    if (oldProvider) {
        reset();
        connectionAdded.disconnect();
        connectionRemoved.disconnect();
        connectionChanged.disconnect();
        context = NULL;
    }
    if (newProvider) context = const_cast<ServiceProvider*>(newProvider);
}

